{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#f6efe7; --card:#fff5ea; --accent:#8a5a3b; --muted:#7b6a63; --glass:rgba(255,255,255,0.6);
      --radius:14px; --maxw:1100px; --gap:28px; font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
    }
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#2f2a27}
    header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));border-bottom:1px solid rgba(0,0,0,0.04);z-index:40}
    .nav{max-width:var(--maxw);margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:18px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#f0d8c6,#efd6bb);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:var(--maxw);margin:36px auto;padding:0 20px;display:grid;gap:var(--gap)}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .card{background:var(--card);padding:26px;border-radius:var(--radius);box-shadow:0 8px 30px rgba(110,80,60,0.06)}
    h1{margin:0 0 8px;font-size:28px;color:var(--accent)}
    p.lead{margin:0;color:#4b433f}
    .intro-list{display:grid;gap:12px;margin-top:16px}
    .pill{display:inline-block;background:linear-gradient(90deg,#fff7f0,#fff2ea);padding:6px 10px;border-radius:999px;font-weight:700;color:var(--accent);font-size:13px}
    .stats{display:flex;flex-direction:column;gap:12px}
    .stat{display:flex;align-items:center;gap:12px}
    .stat strong{font-size:18px;color:var(--accent)}
    .section{opacity:0;transform:translateY(18px);transition:all 420ms cubic-bezier(.2,.9,.2,1);}
    .section.revealed{opacity:1;transform:none}
    .grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    footer{max-width:var(--maxw);margin:36px auto;padding:20px;text-align:center;color:var(--muted)}
    .cta{display:inline-block;padding:10px 16px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none;font-weight:700}
    /* subtle decorative pattern using external path (assets/img/pattern.svg) */
    .hero::before{content:"";position:absolute;right:40px;top:120px;width:240px;height:240px;background-image:url('assets/img/pattern.svg');background-size:cover;opacity:0.06;pointer-events:none}
    @media (max-width:880px){.hero{grid-template-columns:1fr}.hero::before{display:none}}
    @media (prefers-reduced-motion:reduce){.section{transition:none!important;transform:none!important;opacity:1!important}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand"><div class="logo">W</div><div><div style="font-weight:800">{{BUSINESS_NAME}}</div><div style="font-size:12px;color:var(--muted)">A modern approach to daily steadiness</div></div></div>
      <nav aria-label="Main navigation">
        <a href="index.html">Home</a>
        <a href="about.html">Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Journeys</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Voices</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>
  <main>
    <section class="hero section" id="hero">
      <div class="card">
        <span class="pill">Welcome</span>
        <h1>Meet the guide for your everyday rhythms</h1>
        <p class="lead">I help people cultivate dependable habits, clear decision frameworks, and gentle rituals that keep energy even across busy weeks. Practical, evidence-minded, human-centered coaching without gimmicks.</p>
        <div style="margin-top:18px;display:flex;gap:12px;align-items:center">
          <a class="cta" href="book.html">Book a discovery session</a>
          <a href="contact.html" style="color:var(--muted);font-weight:700;text-decoration:none">Ask a question</a>
        </div>
      </div>
      <aside class="card stats">
        <div class="stat"><strong>12</strong><span style="color:var(--muted)">Years coaching adults in transitions</span></div>
        <div class="stat"><strong>3</strong><span style="color:var(--muted)">Signature frameworks for habit design</span></div>
        <div class="stat"><strong>{{CITY}}</strong><span style="color:var(--muted)">Based in {{STATE}}</span></div>
      </aside>
    </section>

    <section class="section" id="values">
      <div class="card">
        <h2 style="margin-top:0;color:var(--accent)">How I work</h2>
        <div class="grid-2">
          <div>
            <h3 style="margin:0 0 6px">Clarity-first</h3>
            <p style="margin:0;color:var(--muted)">We start by naming what matters most now — this narrows choices and reduces friction when habits are formed.</p>
          </div>
          <div>
            <h3 style="margin:0 0 6px">Coaching you can use</h3>
            <p style="margin:0;color:var(--muted)">Short, repeatable practices and check-ins replace complicated plans. Each step connects to daily life.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="frameworks">
      <div class="card">
        <h2 style="margin-top:0;color:var(--accent)">Frameworks I bring</h2>
        <ul style="margin:12px 0 0;color:var(--muted)">
          <li>Anchor-Cue-Reward mapped habits for morning + evening routines</li>
          <li>Energy mapping for realistic scheduling (no more overbooked days)</li>
          <li>Micro-commitment ladder to scale new habits without overwhelm</li>
        </ul>
      </div>
    </section>

    <section class="section" id="story">
      <div class="card">
        <h2 style="margin-top:0;color:var(--accent)">My story, briefly</h2>
        <p style="color:var(--muted)">I trained in applied behavior practices and coached in community and corporate settings. Over time I tuned what works into short, clear routines tailored to the person — not the other way around.</p>
        <p style="color:var(--muted)"><strong>Reach:</strong> Individuals balancing work, family, and care work who want steady days without a heavy plan.</p>
      </div>
    </section>

    <section class="section" id="cta">
      <div class="card" style="text-align:center">
        <h2 style="margin-top:0;color:var(--accent)">Ready to map a sustainable next step?</h2>
        <p style="color:var(--muted)">Start with a focused session that produces a tangible plan you can use the next day.</p>
        <a class="cta" href="book.html">Reserve your focused session</a>
      </div>
    </section>
  </main>
  <footer>
    <div style="font-size:13px">Questions? Call <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
      const reveal = (el)=>{ el.classList.add('revealed'); };
      if(prefersReduced){document.querySelectorAll('.section').forEach(reveal);return}
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting) { reveal(e.target); io.unobserve(e.target); } });
      },{threshold:0.12});
      document.querySelectorAll('.section').forEach(s=>io.observe(s));
    })();
  </script>
</body>
</html>"} 
