<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Services — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff8f2;--card:#fff6f0;--accent:#7b4b36;--muted:#6a5a52;--radius:12px;--maxw:1100px}
    body{margin:0;background:var(--bg);color:#28221f;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    header{position:sticky;top:0;background:rgba(255,255,255,0.7);backdrop-filter:blur(4px);border-bottom:1px solid rgba(0,0,0,0.04)}
    .nav{max-width:var(--maxw);margin:0 auto;padding:14px;display:flex;align-items:center;justify-content:space-between}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#f3e0d2,#f5dbca);display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--accent)}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:700}
    main{max-width:var(--maxw);margin:34px auto;padding:0 20px;display:grid;gap:22px}
    .hero{display:block}
    .hero .card{padding:22px;border-radius:var(--radius);background:var(--card)}
    h1{color:var(--accent);margin:0 0 6px}
    .subtitle{color:var(--muted);margin:0 0 14px}
    .offer-list{display:grid;gap:14px}
    .offer{display:flex;gap:14px;align-items:flex-start;padding:14px;border-radius:10px;background:#fff;box-shadow:0 6px 18px rgba(120,80,60,0.04)}
    .offer .tag{font-size:13px;color:var(--accent);font-weight:700}
    .price{margin-left:auto;font-weight:800;color:var(--accent)}
    .card.small{padding:12px}
    .section{opacity:0;transform:translateY(14px);transition:all 420ms cubic-bezier(.2,.9,.2,1)}
    .section.revealed{opacity:1;transform:none}
    .planner{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fff7f4)}
    label{display:block;font-weight:700;margin-bottom:6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #efe1d7;background:transparent}
    button{background:var(--accent);color:#fff;padding:10px 12px;border-radius:8px;border:none;font-weight:700}
    .result{white-space:pre-wrap;background:#fff;padding:12px;border-radius:8px;border:1px dashed #efdfd6}
    @media (prefers-reduced-motion:reduce){.section{transition:none!important;opacity:1!important;transform:none!important}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div style="display:flex;align-items:center;gap:12px"><div class="logo">W</div><div style="font-weight:800">{{BUSINESS_NAME}}</div></div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Journeys</a>
        <a href="pricing.html">Investment</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero section" id="hero">
      <div class="card">
        <h1>Offerings designed for steady momentum</h1>
        <p class="subtitle">Action-focused services that produce a usable plan after the session. Choose the shape that fits your life rhythm.</p>
      </div>
    </section>

    <section class="section" id="list">
      <div class="offer-list">
        <div class="offer">
          <div>
            <div class="tag">Focused Session</div>
            <div style="font-weight:700">60-minute planning session</div>
            <div style="color:var(--muted)">One deep session that yields a one-week scaffold you can try immediately.</div>
          </div>
          <div class="price">$155</div>
        </div>
        <div class="offer">
          <div>
            <div class="tag">Momentum Package</div>
            <div style="font-weight:700">4-session sequence</div>
            <div style="color:var(--muted)">Monthly cadence to install 2-3 micro-habits and adjust responsively.</div>
          </div>
          <div class="price">$540</div>
        </div>
        <div class="offer">
          <div>
            <div class="tag">Intensive Reset</div>
            <div style="font-weight:700">Deep two-week focus</div>
            <div style="color:var(--muted)">Daily short practices and two coaching calls to reframe routines and energy windows.</div>
          </div>
          <div class="price">Custom</div>
        </div>
      </div>
    </section>

    <section class="section" id="planner">
      <div class="card planner">
        <h2 style="margin-top:0;color:var(--accent)">Session Planner</h2>
        <p style="color:var(--muted);margin:0 0 12px">Build a compact plan for the next week. Copy the plain-text summary and paste it into notes or your calendar.</p>
        <form id="plannerForm" onsubmit="return false" style="display:grid;gap:10px">
          <div>
            <label for="focus">Primary focus for the session</label>
            <select id="focus" required>
              <option value="clarity">Clarify priorities</option>
              <option value="sleep">Improve sleep rhythm</option>
              <option value="energy">Stabilize energy across the day</option>
              <option value="morning">Simplify morning routine</option>
            </select>
          </div>
          <div>
            <label for="length">Preferred session length</label>
            <select id="length">
              <option>30 minutes</option>
              <option selected>60 minutes</option>
              <option>90 minutes</option>
            </select>
          </div>
          <div>
            <label for="frequency">Follow-up frequency</label>
            <select id="frequency">
              <option>Weekly</option>
              <option>Biweekly</option>
              <option>Monthly</option>
            </select>
          </div>
          <div>
            <label for="practices">Preferred practices (choose up to 3)</label>
            <select id="practices" multiple size="3">
              <option>Brief morning ritual</option>
              <option>10-minute midday reset</option>
              <option>Evening wind-down</option>
              <option>Habit pairing (anchor-based)</option>
              <option>Energy mapping</option>
            </select>
            <small style="color:var(--muted)">Hold ctrl/cmd to select multiple</small>
          </div>
          <div>
            <label for="notes">Current habits or constraints</label>
            <textarea id="notes" rows="3" placeholder="e.g., childcare mornings, late-night work, alternating shifts"></textarea>
          </div>
          <div style="display:flex;gap:10px;align-items:center">
            <button id="build">Build plan</button>
            <button id="copy" type="button" style="background:#5b4a42">Copy summary</button>
            <div id="copyStatus" style="color:var(--muted);font-weight:700"></div>
          </div>
        </form>

        <div style="margin-top:12px">
          <h3 style="margin:0 0 6px">Plan summary</h3>
          <div id="summary" class="result">No plan built yet.</div>
        </div>
      </div>
    </section>

    <section class="section" id="faq">
      <div class="card">
        <h2 style="margin-top:0;color:var(--accent)">Frequently asked</h2>
        <details style="margin-bottom:8px"><summary style="font-weight:700">Is this medical advice?</summary><div style="color:var(--muted)">No. Coaching focuses on habits, routines, and practical frameworks — not medical diagnosis or treatment.</div></details>
        <details style="margin-bottom:8px"><summary style="font-weight:700">How soon will I see changes?</summary><div style="color:var(--muted)">You’ll get a usable scaffold immediately; habit shifts show noticeable effects in 2–6 weeks depending on frequency and context.</div></details>
      </div>
    </section>

    <section class="section" id="final-cta">
      <div class="card small" style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-weight:800">Ready to try a focused session?</div>
          <div style="color:var(--muted)">Book a time and bring the plan you just built.</div>
        </div>
        <a class="cta" href="book.html" style="text-decoration:none;padding:10px 12px;background:var(--accent);color:#fff;border-radius:8px;font-weight:800">Reserve a session</a>
      </div>
    </section>

  </main>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
      const reveal = (el)=> el.classList.add('revealed');
      if(prefersReduced){document.querySelectorAll('.section').forEach(reveal);return}
      const io = new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){reveal(e.target);io.unobserve(e.target)}});},{threshold:0.12});
      document.querySelectorAll('.section').forEach(s=>io.observe(s));
    })();

    // Session Planner logic
    (function(){
      const $ = (id)=>document.getElementById(id);
      const buildBtn = $('build');
      const copyBtn = $('copy');
      const summary = $('summary');
      const status = $('copyStatus');

      function readMulti(select){
        return Array.from(select.selectedOptions).map(o=>o.text).slice(0,3);
      }

      function buildPlan(){
        const focusMap = {
          clarity:'Clarify priorities and create a single-week priorities list',
          sleep:'Adjust evening anchors and light exposure to smooth sleep timing',
          energy:'Map energy highs and lows; schedule priorities in high windows',
          morning:'Reduce decision load in the morning with 3 simple anchors'
        };
        const focus = $('focus').value;
        const length = $('length').value;
        const frequency = $('frequency').value;
        const practices = readMulti($('practices'));
        const notes = $('notes').value.trim() || 'No constraints noted.';

        const planLines = [];
        planLines.push('Session Plan — '+ new Date().toLocaleDateString());
        planLines.push('Primary focus: ' + (focusMap[focus]||focus));
        planLines.push('Session length: ' + length + ' | Follow-up: ' + frequency);
        if(practices.length) planLines.push('Suggested practices: ' + practices.join(', '));
        else planLines.push('Suggested practices: none selected');
        planLines.push('Context notes: ' + notes);
        planLines.push('Immediate next steps:');
        planLines.push('- Identify 1 priority to schedule in your best energy window');
        planLines.push('- Add one micro-practice (2–10 minutes) to anchor to an existing routine');
        planLines.push('- Note a single metric to check next week (ease, consistency, or energy)');

        const out = planLines.join('\n');
        summary.textContent = out;
        return out;
      }

      buildBtn.addEventListener('click',function(){
        const out = buildPlan();
        status.textContent = 'Plan ready';
        setTimeout(()=>status.textContent='',2500);
      });

      copyBtn.addEventListener('click',async function(){
        const text = summary.textContent;
        if(!text || text==='No plan built yet.') return; 
        try{
          await navigator.clipboard.writeText(text);
          status.textContent = 'Copied';
          setTimeout(()=>status.textContent='',2000);
        }catch(err){
          status.textContent = 'Copy failed';
          setTimeout(()=>status.textContent='',2000);
        }
      });

      // Enhance accessibility: allow Enter on build when focused
      $('plannerForm').addEventListener('keydown',function(e){ if(e.key==='Enter' && e.target.tagName!=='TEXTAREA'){ e.preventDefault(); buildBtn.click(); } });
    })();
  </script>
</body>
</html>"} 
