        <div style="font-weight:800;color:var(--accent)">Next cohort</div>
        <div style="color:var(--muted);margin-top:6px">Rolling start — small groups and private tracks available. <a href="contact.html" style="color:var(--accent);text-decoration:none">Inquire</a></div>
      </aside>
    </section>

    <section class="section" id="program-list">
      <div class="programs">
