          <a href="book.html" style="margin-top:auto;text-decoration:none;display:inline-block;padding:8px;border-radius:8px;background:var(--accent);color:#fff;font-weight:800">Join seed</a>
        </div>
        <div class="prog">
          <div style="font-weight:800">Flow: 8-week energy mapping</div>
