  <script>
    // Scroll reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
      const reveal = (el)=> el.classList.add('revealed');
      if(prefersReduced){document.querySelectorAll('.section').forEach(reveal);return}
      const io = new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){reveal(e.target);io.unobserve(e.target)}});},{threshold:0.12});
      document.querySelectorAll('.section').forEach(s=>io.observe(s));
    })();

    // Planner for program matching
    (function(){
      const $ = id=>document.getElementById(id);
      const build = $('build2'); const copy = $('copy2'); const summary = $('summary2'); const status = $('status2');

      function match(){
        const goal = $('goal').value; const avail = $('avail').value; const support = $('support').value; const notes = $('constraints').value.trim() || '—';
        const lines = [];
        lines.push('Program match — ' + new Date().toLocaleDateString());
        lines.push('Goal: ' + goal.replace(/^[a-z]/,c=>c.toUpperCase()));
        lines.push('Weekly availability: ' + avail);
        lines.push('Accountability: ' + support);
        lines.push('Notes: ' + notes);
        lines.push('Recommendation:');
        if(goal==='launch') lines.push('- Seed (3-week habit starter) — ideal for focused, small-time commitments');
        else if(goal==='stabilize') lines.push('- Flow (8-week energy mapping) — best when you can invest 2–3 hours weekly');
        else lines.push('- Anchor (habit pairing intensive) — for bundling multiple habits into routines');
        if(support==='Small group') lines.push('Consider the cohort option for social accountability.');
        return lines.join('\n');
      }

      build.addEventListener('click',function(){ summary.textContent = match(); status.textContent='Ready'; setTimeout(()=>status.textContent='',2000); });
      copy.addEventListener('click',async function(){ if(!summary.textContent || summary.textContent==='No match yet.') return; try{ await navigator.clipboard.writeText(summary.textContent); status.textContent='Copied'; setTimeout(()=>status.textContent='',2000);}catch(e){status.textContent='Copy failed';setTimeout(()=>status.textContent='',2000);} });
    })();
  </script>
